import sys

def main():
    lines = [l.strip() for l in sys.stdin.read().strip().splitlines() if l.strip()]
    if not lines:
        return
    n = int(lines[0])
    d1 = {}
    idx = 1
    for _ in range(n):
        k, v = lines[idx].split(maxsplit=1)
        d1[k] = int(v)
        idx += 1
    d2 = d1
    mod_k, mod_v = lines[idx].split(maxsplit=1)
    d2[mod_k] = int(mod_v)

    sorted_d1 = {k: d1[k] for k in sorted(d1.keys())}
    sorted_d2 = {k: d2[k] for k in sorted(d2.keys())}
    print(f"d1: {sorted_d1}")
    print(f"d2: {sorted_d2}")
    print(f"same_object: {d1 is d2}")

if __name__ == "__main__":
    main()

import sys

def main():
    lines = [l.strip() for l in sys.stdin.read().strip().splitlines() if l.strip()]
    if not lines:
        return

    def parse_val(v):
        if v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
            return int(v)
        return v

    n = int(lines[0])
    idx = 1
    d = {}
    for _ in range(n):
        parts = lines[idx].split(maxsplit=1)
        d[parts[0]] = parse_val(parts[1])
        idx += 1

    m = int(lines[idx])
    idx += 1
    for _ in range(m):
        parts = lines[idx].split(maxsplit=1)
        d[parts[0]] = parse_val(parts[1])
        idx += 1

    for k in sorted(d.keys()):
        print(f"{k}: {d[k]}")

if __name__ == "__main__":
    main()

import sys

def main():
    lines = [l.rstrip("\r\n") for l in sys.stdin.read().splitlines()]
    file_lines = []
    out = []
    for line in lines:
        line_str = line.strip()
        if not line_str:
            continue
        if line_str == "EXIT":
            break
        elif line_str.startswith("WRITE "):
            content = line[6:]
            file_lines = [content]
        elif line_str.startswith("APPEND "):
            content = line[7:]
            file_lines.append(content)
        elif line_str == "COUNT":
            out.append(f"lines: {len(file_lines)}")
        elif line_str == "READ":
            if not file_lines:
                out.append("--- EMPTY ---")
            else:
                out.extend(file_lines)
    for l in out:
        print(l)

if __name__ == "__main__":
    main()

import sys
import string

def main():
    text = sys.stdin.read().lower()
    translator = str.maketrans('', '', string.punctuation)
    cleaned = text.translate(translator)
    words = cleaned.split()
    if not words:
        print("--- NO WORDS ---")
        return
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    sorted_words = sorted(freq.items(), key=lambda item: (-item[1], item[0]))
    for w, c in sorted_words:
        print(f"{w}: {c}")

if __name__ == "__main__":
    main()

import sys

def main():
    lines = [l.strip() for l in sys.stdin.read().strip().splitlines() if l.strip()]
    if not lines:
        return
    nums = [int(x) for x in lines[0].split()]
    d_val, p_val = [int(x) for x in lines[1].split()]

    filtered_squares = [x**2 for x in nums if x >= p_val and x % d_val != 0]
    dict_mapping = {x: (x**2, x % 2 == 0) for x in nums if x >= p_val and x % d_val != 0}
    sorted_dict = {k: dict_mapping[k] for k in sorted(dict_mapping.keys())}

    print(f"filtered_squares: {filtered_squares}")
    print(f"dict_mapping: {sorted_dict}")

if __name__ == "__main__":
    main()

import sys

def main():
    moves = sys.stdin.read().strip().split()
    x, y = 0, 0
    visits = {(0, 0): 1}

    for m in moves:
        m = m.upper()
        if m == "UP":
            y += 1
        elif m == "DOWN":
            y -= 1
        elif m == "RIGHT":
            x += 1
        elif m == "LEFT":
            x -= 1
        pos = (x, y)
        visits[pos] = visits.get(pos, 0) + 1

    unhashable_caught = False
    try:
        bad_dict = {[x, y]: 1}
    except TypeError:
        unhashable_caught = True

    most_visited_pos = sorted(visits.items(), key=lambda item: (-item[1], item[0][0], item[0][1]))[0]

    print(f"final_position: {(x, y)}")
    print(f"unique_positions: {len(visits)}")
    print(f"most_visited: {most_visited_pos[0]} with {most_visited_pos[1]} visits")
    print(f"unhashable_caught: {unhashable_caught}")

if __name__ == "__main__":
    main()
